INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (11, 39, 'theory', 'Quiz: project, tests and deploy');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 39, 0, 'Why does the Vite dev server start almost instantly?', '["It builds the whole project into one file in advance", "It serves modules to the browser on request and transforms them on the fly", "It does not process TypeScript", "It works on a single file only"]', 1, 'The browser loads ES modules itself, and Vite transforms only the requested files; dependencies are built once and cached.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 39, 1, 'Why add a content hash to built file names?', '["So files take up less space", "So unchanged files come from the cache and changed ones are downloaded again", "To hide the source code", "Because the browser requires it"]', 1, 'The hash changes with the content: you can cache a file for a long time without fearing a stale version.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 39, 2, 'Which tests in the "pyramid" should be the most numerous?', '["End-to-end tests in a browser", "Unit tests: fast checks of functions and modules", "Manual checks", "All kinds equally"]', 1, 'Unit tests are fast and stable, so they form the base of the pyramid; end-to-end tests are few and only for the main scenarios.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 39, 3, 'What must you configure on the hosting for an app with client-side routing?', '["Disable caching of all files", "Serve the main page (index.html) for unknown paths", "Forbid page refresh", "Nothing"]', 1, 'Otherwise, on reload at an address like /users/42, the server returns 404: there is no such file on disk.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 39, 4, 'What is continuous integration (CI) for?', '["To replace tests", "To run checks, tests and the build in a clean environment on every commit", "To speed up the browser", "To store the source code"]', 1, 'CI makes checks mandatory and independent of anyone''s machine: a red pipeline blocks the merge.');
